@startuml

class Employee {
  +identifyingNumber : int
  +name : string
  +address : string
}

class Part {
  +category : string
  +serialNumber : string
  +price : double
}

class Car {
  +licensePlate : string
  +make : string
  +model : string
  +color : string
}

class Owner {
  +identifyingNumber : int
  +name : string
  +address : string
  +phone : string
}

class AssemblyService {
  +kms : int
  +workHours : int
  +admissionDate : date
  +finishDate : date
}

Employee "1" -- "*" AssemblyService : is responsible for
AssemblyService "*" -- "1" Car : executed in
AssemblyService "*" -- "1..*" Part : fits
Car "1" -- "0..*" AssemblyService : undergoes
Car "*" -- "0..1" Owner : is owned by
Owner "1" -- "*" Car : owns

@enduml

